 j constant jsonb := $records$[{"id": "64ce5de9-2235-43f2-914b-1c5519776d56", "recipe_group_id": "16e07d31-b2fb-47b8-a740-92d66b253ea1", "language": "es", "slug": "receta-de-rollos-de-berenjena-con-tomates", "public_path": "/receta-de-rollos-de-berenjena-con-tomates", "source_url": "https://manualdecocina.com/receta-de-rollos-de-berenjena-con-tomates/", "title": "Rollos de berenjena con tomate y ricotta", "excerpt": "Doce rollos de berenjena asada con ricotta y salsa de tomate casera. Cuatro raciones con dos horneados y reparto medido de aceite, sal y orégano.", "category": "Platos principales", "category_slug": "platos-principales", "cuisine": "Inspiración italiana", "difficulty": "Media", "servings": 4, "image_url": "/recetas/receta-de-rollos-de-berenjena-con-tomates/portada.webp", "ingredients": [{"amount": 800, "unit": "g", "name": "berenjena cruda, parte comestible", "group": "Ingredientes"}, {"amount": 500, "unit": "g", "name": "tomate maduro", "group": "Ingredientes"}, {"amount": 200, "unit": "g", "name": "queso ricotta de leche entera", "group": "Ingredientes"}, {"amount": 30, "unit": "g", "name": "aceite de oliva", "group": "Ingredientes"}, {"amount": 8, "unit": "g", "name": "ajo pelado", "group": "Ingredientes"}, {"amount": 2, "unit": "g", "name": "orégano seco", "group": "Ingredientes"}, {"amount": 3, "unit": "g", "name": "sal fina", "group": "Ingredientes"}], "steps": [{"title": "Prepara y corta las berenjenas", "content": "Precalienta el horno a 200 °C. Lava la berenjena, retira los extremos y pesa 800 g de parte comestible. Corta a lo largo unas 12 láminas de 5 mm; reserva los recortes para otro uso y no los cuentes en ese peso. Pesa tomate, ricotta, aceite, ajo, orégano y sal.", "image_url": "/recetas/receta-de-rollos-de-berenjena-con-tomates/paso-01.webp", "image_alt": "Rollos de berenjena con tomate y ricotta: prepara y corta las berenjenas"}, {"title": "Asa las láminas", "content": "Coloca las 12 láminas en dos bandejas con papel para horno, sin superponer. Pincela ambas caras con 20 g del aceite y reparte 1 g de sal. Hornea unos 20 minutos, intercambiando las bandejas a mitad, hasta que se doblen sin romperse. No busques dejarlas crujientes; mantén el horno encendido.", "image_url": "/recetas/receta-de-rollos-de-berenjena-con-tomates/paso-02.webp", "image_alt": "Rollos de berenjena con tomate y ricotta: asa las láminas"}, {"title": "Cocina la salsa de tomate", "content": "Mientras se asan, pica los 500 g de tomate y 8 g de ajo. Calienta los 10 g restantes de aceite en una sartén; añade ajo durante 30 segundos, sin dorarlo. Incorpora tomate, 1 g de orégano y 1 g de sal. Cocina 15 minutos a fuego medio, removiendo, hasta obtener una salsa espesa.", "image_url": "/recetas/receta-de-rollos-de-berenjena-con-tomates/paso-03.webp", "image_alt": "Rollos de berenjena con tomate y ricotta: cocina la salsa de tomate"}, {"title": "Prepara el relleno", "content": "Mezcla los 200 g de ricotta con el 1 g restante de orégano y el 1 g restante de sal. No añadas huevo ni otro queso. Deja las láminas unos minutos hasta poder manipularlas y divide visualmente el relleno en 12 partes iguales para repartirlo por todos los rollos.", "image_url": "/recetas/receta-de-rollos-de-berenjena-con-tomates/paso-04.webp", "image_alt": "Rollos de berenjena con tomate y ricotta: prepara el relleno"}, {"title": "Forma y coloca los rollos", "content": "Extiende la mitad de la salsa en una fuente de unos 25 × 20 cm. Pon una porción de ricotta en un extremo de cada lámina y enrolla suavemente. Coloca los 12 rollos con la unión hacia abajo, juntos en una capa. Cubre con el resto de la salsa.", "image_url": "/recetas/receta-de-rollos-de-berenjena-con-tomates/paso-05.webp", "image_alt": "Rollos de berenjena con tomate y ricotta: forma y coloca los rollos"}, {"title": "Hornea el conjunto", "content": "Hornea a 200 °C unos 20 minutos, hasta que la salsa burbujee y el relleno esté caliente. Las láminas ya se han asado; este segundo horneado calienta el conjunto y reúne los sabores. Si salen frías del refrigerador, necesitarán más tiempo; no uses los 20 minutos como garantía.", "image_url": "/recetas/receta-de-rollos-de-berenjena-con-tomates/paso-06.webp", "image_alt": "Rollos de berenjena con tomate y ricotta: hornea el conjunto"}, {"title": "Deja reposar y sirve", "content": "Deja reposar 5 minutos fuera del horno y sirve tres rollos por persona, con la salsa, para cuatro raciones. El total de 65 minutos incluye 20 de preparación, 40 de horno y 5 de reposo; los 15 de salsa se solapan con el primer horneado. No incluye acompañamientos ni decoraciones.", "image_url": "/recetas/receta-de-rollos-de-berenjena-con-tomates/paso-07.webp", "image_alt": "Rollos de berenjena con tomate y ricotta: deja reposar y sirve"}], "notes": "Fórmula original pendiente de prueba de cocina. Contiene leche. Se usan 800 g de láminas comestibles: compra más para compensar extremos y recortes. Las láminas deben ser flexibles antes de enrollarlas. Nutrición para toda la fórmula repartida en cuatro; sin guarnición. Refrigera las sobras dentro de 2 horas en recipientes poco profundos, a 4 °C o menos, y consume en 3–4 días; recalienta a 74 °C.", "seo": {"title": "Rollos de berenjena con tomate y ricotta: receta paso a paso", "description": "Doce rollos de berenjena asada con ricotta y salsa de tomate casera. Cuatro raciones con dos horneados y reparto medido de aceite, sal y orégano.", "about": "Doce rollos de berenjena asada con ricotta y salsa de tomate casera. Cuatro raciones con dos horneados y reparto medido de aceite, sal y orégano.", "faq": [{"q": "¿Puedo usar berenjena cruda para enrollar?", "a": "No en esta fórmula: primero se asa hasta que sea flexible, para que no se rompa al enrollar."}, {"q": "¿El relleno lleva huevo?", "a": "No. Solo ricotta, orégano y sal en las cantidades indicadas."}, {"q": "¿Puedo prepararlo con antelación?", "a": "Sí: refrigera el conjunto. El horneado desde frío necesitará más tiempo; calienta completamente 