DECLARE
 j constant jsonb := $records$[{"id": "1eda6abc-48cd-42bb-a64d-2c785df6ea4e", "recipe_group_id": "de2ec78c-3533-49db-92f0-db85d9884015", "language": "es", "slug": "receta-torta-de-zanahoria", "public_path": "/receta-torta-de-zanahoria", "source_url": "https://manualdecocina.com/receta-torta-de-zanahoria/", "title": "Torta de zanahoria sin cobertura", "excerpt": "Torta de zanahoria con canela, hecha en un molde de 20 cm y servida sin cobertura. Ocho porciones, con ingredientes pesados y enfriado incluido.", "category": "Postres", "category_slug": "postres", "cuisine": "Cocina casera", "difficulty": "Media", "servings": 8, "image_url": "/recetas/receta-torta-de-zanahoria/portada.webp", "ingredients": [{"amount": 250, "unit": "g", "name": "zanahoria pelada", "group": "Ingredientes"}, {"amount": 200, "unit": "g", "name": "harina de trigo común", "group": "Ingredientes"}, {"amount": 160, "unit": "g", "name": "azúcar blanco", "group": "Ingredientes"}, {"amount": 120, "unit": "g", "name": "huevo crudo sin cáscara", "group": "Ingredientes"}, {"amount": 100, "unit": "g", "name": "aceite de canola", "group": "Ingredientes"}, {"amount": 8, "unit": "g", "name": "polvo de hornear", "group": "Ingredientes"}, {"amount": 3, "unit": "g", "name": "canela molida", "group": "Ingredientes"}, {"amount": 1, "unit": "g", "name": "sal fina", "group": "Ingredientes"}], "steps": [{"title": "Prepara el molde y pesa", "content": "Precalienta el horno a 175 °C, calor arriba y abajo. Forra base y paredes de un molde redondo de 20 cm con papel para hornear. Pesa todos los ingredientes; los 120 g de huevo se pesan sin cáscara y los 250 g de zanahoria, después de pelarla. No añadas aceite al molde: ya está forrado.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-01.webp", "image_alt": "Torta de zanahoria sin cobertura: prepara el molde y pesa"}, {"title": "Mezcla los ingredientes secos", "content": "Tamiza juntos 200 g de harina y 8 g de polvo de hornear en un cuenco. Añade 3 g de canela molida y 1 g de sal. Remueve para distribuir el impulsor; así no quedan zonas con sabor concentrado ni un levado desigual. Reserva esta mezcla seca.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-02.webp", "image_alt": "Torta de zanahoria sin cobertura: mezcla los ingredientes secos"}, {"title": "Bate huevo, azúcar y aceite", "content": "En otro cuenco bate 120 g de huevo con 160 g de azúcar durante 2 minutos, hasta integrar. Añade 100 g de aceite de canola en un hilo mientras remueves. No necesitas montar los huevos ni duplicar su volumen: busca una mezcla uniforme, sin aceite separado.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-03.webp", "image_alt": "Torta de zanahoria sin cobertura: bate huevo, azúcar y aceite"}, {"title": "Ralla la zanahoria", "content": "Ralla finamente los 250 g de zanahoria pelada y añádelos a los líquidos. Incorpora con espátula para repartirlos. Usa la zanahoria con su humedad natural, sin escurrirla; los trozos gruesos tardarían más en ablandarse y cambiarían la textura prevista.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-04.webp", "image_alt": "Torta de zanahoria sin cobertura: ralla la zanahoria"}, {"title": "Incorpora la harina", "content": "Añade la mezcla seca en dos veces. Usa la espátula para levantar la masa desde el fondo y girar el cuenco, solo hasta que no queden bolsas de harina. No batas de forma prolongada una vez añadida la harina. La masa quedará espesa, húmeda y con zanahoria visible.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-05.webp", "image_alt": "Torta de zanahoria sin cobertura: incorpora la harina"}, {"title": "Llena el molde", "content": "Vierte toda la masa en el molde preparado y nivela suavemente la superficie. Da un golpe leve del molde sobre un paño para quitar bolsas de aire grandes. Lleva inmediatamente al centro del horno; no dejes reposar la masa antes de hornear.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-06.webp", "image_alt": "Torta de zanahoria sin cobertura: llena el molde"}, {"title": "Hornea y comprueba el centro", "content": "Hornea unos 40 minutos a 175 °C. Comprueba desde el minuto 35: un palillo introducido en el centro debe salir sin masa líquida, aunque puede tener migas húmedas. Si aún sale masa, hornea 5 minutos más y repite. No uses solo el color exterior para decidir; suma cualquier tiempo adicional.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-07.webp", "image_alt": "Torta de zanahoria sin cobertura: hornea y comprueba el centro"}, {"title": "Enfría, desmolda y sirve", "content": "Deja el pastel 15 minutos en el molde. Desmolda sobre rejilla, retira el papel y espera otros 30 minutos antes de cortar en ocho porciones. Se sirve sin cobertura, frutos secos ni guarnición. El total previsto de 105 minutos incluye 45 de enfriado; si necesitas más horno o enfriado, añádelo.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-08.webp", "image_alt": "Torta de zanahoria sin cobertura: enfría, desmolda y sirve"}], "notes": "Fórmula original pendiente de prueba de cocina. Contiene trigo y huevo. El peso de huevo excluye la cáscara. No incluye cobertura ni frutos secos. Una harina distinta o un molde diferente cambia el resultado y el tiempo. Guarda el pastel frío en un recipiente cerrado; refrigera si no vas a consumirlo pronto y deja atemperar la porción antes de servir.", "seo": {"title": "Torta de zanahoria sin cobertura: receta paso a paso", "description": "Torta de zanahoria con canela, hecha en un molde de 20 cm y servida sin cobertura. Ocho porciones, con ingredientes pesados y enfriado incluido.", "about": "Torta de zanahoria con canela, hecha en un molde de 20 cm y servida sin cobertura. Ocho porciones, con ingredientes pesados y enfriado incluido.", "faq": [{"q": "¿Lleva cobertura de queso?", "a": "No. Esta fórmula se sirve sin cobertura; añadirla cambia ingredientes, tiempo y nutrición."}, {"q": "¿Puedo usar un molde más pequeño?", "a": "La masa quedará más alta y necesitará otro tiempo. La referencia es un molde de 20 cm; comprueba siempre el centro."}, {"q": "¿Por qué no se escurre la zanahoria?", "a": "La fórmula cuenta su humedad natural. Escurrirla cambia el equilibrio entre líquidos y harina."}], "image_alt": "Torta de zanahoria sin cobertura", "image_variants": ["/recetas/receta-torta-de-zanahoria/portada-1x1.webp", "/recetas/receta-torta-de-zanahoria/portada-4x3.webp", "/recetas/receta-torta-de-zanahoria/portada-16x9.webp"]}, "nutrition": {"calories": 314.6, "protein_g": 4.8, "carbs_g": 42.7, "fat_g": 14.3, "saturated_fat_g": 1.4, "fiber_g": 1.8, "sugar_g": 21.6, "sodium_mg": 171.0, "serving_size": "Una de 8 raciones iguales", "estimated": true, "source": "USDA FoodData Central — SR Legacy (2018)", "method": "Suma de gramos de ingredientes × nutrientes USDA por 100 g, dividida entre 8. Pesos iniciales de partes comestibles; rendimiento cocinado no medido. Se incluye toda la fórmula, sin aplicar pérdidas no medidas.", "note": "Estimación, no análisis de laboratorio ni prueba de cocina. Marcas, restos y rendimiento pueden variar. Se incluye la fórmula completa; no se incluyen acompañamientos.", "inputs": [{"fdc_id": 170393, "description": "Carrots, raw", "recipe_grams": 250, "edible_grams": 250, "per_100g": {"saturated_fat_g": 0.032, "sodium_mg": 69.0, "protein_g": 0.93, "fat_g": 0.24, "sugar_g": 4.74, "carbs_g": 9.58, "calories": 41.0, "fiber_g": 2.8}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 169761, "description": "Wheat flour, white, all-purpose, unenriched", "recipe_grams": 200, "edible_grams": 200, "per_100g": {"fat_g": 0.98, "carbs_g": 76.3, "calories": 364, "fiber_g": 2.7, "sodium_mg": 2.0, "protein_g": 10.3, "saturated_fat_g": 0.155, "sugar_g": 0.27}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 169655, "description": "Sugars, granulated", "recipe_grams": 160, "edible_grams": 160, "per_100g": {"protein_g": 0.0, "sodium_mg": 1.0, "fat_g": 0.0, "calories": 387, "saturated_fat_g": 0.0, "sugar_g": 99.8, "carbs_g": 100, "fiber_g": 0.0}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 171287, "description": "Egg, whole, raw, fresh", "recipe_grams": 120, "edible_grams": 120, "per_100g": {"calories": 143, "saturated_fat_g": 3.13, "protein_g": 12.6, "sodium_mg": 142, "sugar_g": 0.37, "fat_g": 9.51, "carbs_g": 0.72, "fiber_g": 0.0}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 172336, "description": "Oil, canola", "recipe_grams": 100, "edible_grams": 100, "per_100g": {"fat_g": 100, "saturated_fat_g": 7.36, "protein_g": 0.0, "carbs_g": 0.0, "calories": 884, "fiber_g": 0.0, "sodium_mg": 0.0, "sugar_g": 0.0}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 172804, "description": "Leavening agents, baking powder, double-acting, straight phosphate", "recipe_grams": 8, "edible_grams": 8, "per_100g": {"saturated_fat_g": 0.0, "fiber_g": 0.2, "fat_g": 0.0, "carbs_g": 24.1, "calories": 51.0, "protein_g": 0.1, "sodium_mg": 7890.0, "sugar_g": 0.0}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 171320, "description": "Spices, cinnamon, ground", "recipe_grams": 3, "edible_grams": 3, "per_100g": {"sugar_g": 2.17, "fiber_g": 53.1, "protein_g": 3.99, "sodium_mg": 10.0, "saturated_fat_g": 0.345, "fat_g": 1.24, "carbs_g": 80.6, "calories": 247}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 173468, "description": "Salt, table", "recipe_grams": 1, "edible_grams": 1, "per_100g": {"fiber_g": 0.0, "sodium_mg": 38800.0, "saturated_fat_g": 0.0, "protein_g": 0.0, "fat_g": 0.0, "carbs_g": 0.0, "calories": 0.0, "sugar_g": 0.0}, "basis": "initial_edible_formula_grams"}], "source_url": "https://fdc.nal.usda.gov/"}, "prep_time_minutes": 20, "cook_time_minutes": 40, "total_time_minutes": 105, "course": "Postres", "summary": "Torta de zanahoria con canela, hecha en un molde de 20 cm y servida sin cobertura. Ocho porciones, con ingredientes pesados y enfriado incluido.", "content_html": "<p>Torta de zanahoria con canela, hecha en un molde de 20 cm y servida sin cobertura. Ocho porciones, con ingredientes pesados y enfriado incluido.</p>", "keywords": ["Torta de zanahoria sin cobertura"], "gallery": [{"url": "/recetas/receta-torta-de-zanahoria/portada.webp", "alt": "Torta de zanahoria sin cobertura"}], "published": true, "editorial_status": "published"}, {"id": "428d464a-bcf2-5208-bbc8-3d0eedd85587", "recipe_group_id": "de2ec78c-3533-49db-92f0-db85d9884015", "language": "de", "slug": "karottenkuchen-rezept", "public_path": "/de/karottenkuchen-rezept", "source_url": "https://manualdecocina.com/de/karottenkuchen-rezept/", "title": "Karottenkuchen ohne Glasur", "excerpt": "Karottenkuchen mit Zimt aus einer 20 cmForm, ohne Glasur. Acht Stücke, abgewogene Zutaten und eingeplante Abkühlzeit.", "category": "Desserts", "category_slug": "postres", "cuisine": "Hausmannskost", "difficulty": "Mittel", "servings": 8, "image_url": "/recetas/receta-torta-de-zanahoria/portada.webp", "ingredients": [{"amount": 250, "unit": "g", "name": "geschälte Karotten", "group": "Zutaten"}, {"amount": 200, "unit": "g", "name": "Weizenmehl", "group": "Zutaten"}, {"amount": 160, "unit": "g", "name": "weißer Zucker", "group": "Zutaten"}, {"amount": 120, "unit": "g", "name": "rohes Ei ohne Schale", "group": "Zutaten"}, {"amount": 100, "unit": "g", "name": "Rapsöl", "group": "Zutaten"}, {"amount": 8, "unit": "g", "name": "Backpulver", "group": "Zutaten"}, {"amount": 3, "unit": "g", "name": "gemahlener Zimt", "group": "Zutaten"}, {"amount": 1, "unit": "g", "name": "feines Salz", "group": "Zutaten"}], "steps": [{"title": "Form vorbereiten und abwiegen", "content": "Den Ofen auf 175 °C Ober-/Unterhitze vorheizen. Boden und Seiten einer runden 20 cmForm mit Backpapier auslegen. Alle Zutaten abwiegen:120 g Ei ohne Schale und 250 g Karotten nach dem Schälen. Die ausgelegte Form benötigt kein zusätzliches Öl.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-01.webp", "image_alt": "Karottenkuchen ohne Glasur: Form vorbereiten und abwiegen"}, {"title": "Trockene Zutaten mischen", "content": "200 g Mehl und 8 g Backpulver zusammen in eine Schüssel sieben.3 g Zimt und 1 g Salz einrühren, damit sich das Backpulver gleichmäßig verteilt und keine konzentrierten Stellen oder ungleichmäßiges Aufgehen entstehen. Die trockene Mischung beiseitestellen.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-02.webp", "image_alt": "Karottenkuchen ohne Glasur: Trockene Zutaten mischen"}, {"title": "Ei, Zucker und Öl verrühren", "content": "120 g Ei mit 160 g Zucker 2 Minuten verrühren.100 g Rapsöl unter Rühren in dünnem Strahl hinzufügen. Die Eier müssen weder schaumig geschlagen werden noch ihr Volumen verdoppeln: Eine gleichmäßige Mischung ohne abgesetztes Öl reicht.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-03.webp", "image_alt": "Karottenkuchen ohne Glasur: Ei, Zucker und Öl verrühren"}, {"title": "Karotten fein reiben", "content": "250 g geschälte Karotten fein reiben und mit einem Teigschaber unter die flüssige Mischung heben. Die natürliche Feuchtigkeit behalten, nicht ausdrücken. Grobe Stücke brauchen länger, bis sie weich werden, und verändern die vorgesehene Konsistenz.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-04.webp", "image_alt": "Karottenkuchen ohne Glasur: Karotten fein reiben"}, {"title": "Mehl unterheben", "content": "Die trockene Mischung in zwei Portionen hinzufügen. Den Teigschaber vom Boden nach oben führen und die Schüssel drehen, bis keine Mehlnester bleiben. Nach Zugabe des Mehls nicht lange schlagen. Der Teig ist dick und feucht, die Karotten bleiben sichtbar.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-05.webp", "image_alt": "Karottenkuchen ohne Glasur: Mehl unterheben"}, {"title": "Form füllen", "content": "Den gesamten Teig in die vorbereitete Form geben und glatt streichen. Die Form einmal leicht auf ein Küchentuch klopfen, um große Luftblasen zu entfernen. Sofort auf der mittleren Schiene backen; den Teig vorher nicht ruhen lassen.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-06.webp", "image_alt": "Karottenkuchen ohne Glasur: Form füllen"}, {"title": "Backen und Mitte prüfen", "content": "Etwa 40 Minuten bei 175 °C backen. Ab Minute 35 ein Holzstäbchen in die Mitte stecken: Es darf kein flüssiger Teig daran haften, feuchte Krümel sind möglich. Bei flüssigem Teig weitere 5 Minuten backen und erneut prüfen. Nicht nur nach der Außenfarbe entscheiden; zusätzliche Zeit einrechnen.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-07.webp", "image_alt": "Karottenkuchen ohne Glasur: Backen und Mitte prüfen"}, {"title": "Abkühlen, herausnehmen und servieren", "content": "15 Minuten in der Form abkühlen lassen, dann auf ein Gitter setzen und Papier entfernen. Weitere 30 Minuten warten und in acht Stücke schneiden. Ohne Glasur, Nüsse oder Beilage servieren. Die geplanten 105 Minuten enthalten 45 Minuten Abkühlen; längere Back- oder Kühlzeit hinzufügen.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-08.webp", "image_alt": "Karottenkuchen ohne Glasur: Abkühlen, herausnehmen und servieren"}], "notes": "Eigenständiger Rezeptvorschlag, noch nicht in der Küche getestet. Enthält Weizen und Ei. Eimenge ohne Schale. Keine Glasur oder Nüsse enthalten. Andere Mehlsorten oder Formen verändern Ergebnis und Backzeit. Den abgekühlten Kuchen verschlossen lagern; bei späterem Verzehr kühlen und einzelne Portionen vor dem Servieren temperieren.", "seo": {"title": "Karottenkuchen ohne Glasur: Schritt für Schritt", "description": "Karottenkuchen mit Zimt aus einer 20 cmForm, ohne Glasur. Acht Stücke, abgewogene Zutaten und eingeplante Abkühlzeit.", "about": "Karottenkuchen mit Zimt aus einer 20 cmForm, ohne Glasur. Acht Stücke, abgewogene Zutaten und eingeplante Abkühlzeit.", "faq": [{"q": "Hat der Kuchen eine Frischkäseglasur?", "a": "Nein. Eine Glasur würde Zutaten, Zeit und Nährwerte verändern."}, {"q": "Kann ich eine kleinere Form verwenden?", "a": "Der Teig wird höher und benötigt eine andere Backzeit. Die Referenz ist 20 cm; die Mitte stets prüfen."}, {"q": "Warum werden die Karotten nicht ausgedrückt?", "a": "Ihre natürliche Feuchtigkeit gehört zur Formel. Ausdrücken verändert das Verhältnis zwischen Flüssigkeit und Mehl."}], "image_alt": "Karottenkuchen ohne Glasur", "image_variants": ["/recetas/receta-torta-de-zanahoria/portada-1x1.webp", "/recetas/receta-torta-de-zanahoria/portada-4x3.webp", "/recetas/receta-torta-de-zanahoria/portada-16x9.webp"]}, "nutrition": {"calories": 314.6, "protein_g": 4.8, "carbs_g": 42.7, "fat_g": 14.3, "saturated_fat_g": 1.4, "fiber_g": 1.8, "sugar_g": 21.6, "sodium_mg": 171.0, "serving_size": "Eine von 8 gleichen Portionen", "estimated": true, "source": "USDA FoodData Central — SR Legacy (2018)", "method": "Summe der essbaren Ausgangsgewichte in Gramm × USDA-Nährwerte je 100 g, geteilt durch 8. Keine ungemessenen Garverluste angewandt. Die vollständige Formel wird auf acht gleiche Stücke verteilt; keine Glasur, Nüsse oder Beilage eingerechnet.", "note": "Schätzung, keine Laboranalyse oder Küchenprüfung. Marken, Reste und Garertrag können variieren. Die vollständige Formel wird auf acht gleiche Stücke verteilt; keine Glasur, Nüsse oder Beilage eingerechnet.", "inputs": [{"fdc_id": 170393, "description": "Carrots, raw", "recipe_grams": 250, "edible_grams": 250, "per_100g": {"saturated_fat_g": 0.032, "sodium_mg": 69.0, "protein_g": 0.93, "fat_g": 0.24, "sugar_g": 4.74, "carbs_g": 9.58, "calories": 41.0, "fiber_g": 2.8}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 169761, "description": "Wheat flour, white, all-purpose, unenriched", "recipe_grams": 200, "edible_grams": 200, "per_100g": {"fat_g": 0.98, "carbs_g": 76.3, "calories": 364, "fiber_g": 2.7, "sodium_mg": 2.0, "protein_g": 10.3, "saturated_fat_g": 0.155, "sugar_g": 0.27}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 169655, "description": "Sugars, granulated", "recipe_grams": 160, "edible_grams": 160, "per_100g": {"protein_g": 0.0, "sodium_mg": 1.0, "fat_g": 0.0, "calories": 387, "saturated_fat_g": 0.0, "sugar_g": 99.8, "carbs_g": 100, "fiber_g": 0.0}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 171287, "description": "Egg, whole, raw, fresh", "recipe_grams": 120, "edible_grams": 120, "per_100g": {"calories": 143, "saturated_fat_g": 3.13, "protein_g": 12.6, "sodium_mg": 142, "sugar_g": 0.37, "fat_g": 9.51, "carbs_g": 0.72, "fiber_g": 0.0}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 172336, "description": "Oil, canola", "recipe_grams": 100, "edible_grams": 100, "per_100g": {"fat_g": 100, "saturated_fat_g": 7.36, "protein_g": 0.0, "carbs_g": 0.0, "calories": 884, "fiber_g": 0.0, "sodium_mg": 0.0, "sugar_g": 0.0}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 172804, "description": "Leavening agents, baking powder, double-acting, straight phosphate", "recipe_grams": 8, "edible_grams": 8, "per_100g": {"saturated_fat_g": 0.0, "fiber_g": 0.2, "fat_g": 0.0, "carbs_g": 24.1, "calories": 51.0, "protein_g": 0.1, "sodium_mg": 7890.0, "sugar_g": 0.0}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 171320, "description": "Spices, cinnamon, ground", "recipe_grams": 3, "edible_grams": 3, "per_100g": {"sugar_g": 2.17, "fiber_g": 53.1, "protein_g": 3.99, "sodium_mg": 10.0, "saturated_fat_g": 0.345, "fat_g": 1.24, "carbs_g": 80.6, "calories": 247}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 173468, "description": "Salt, table", "recipe_grams": 1, "edible_grams": 1, "per_100g": {"fiber_g": 0.0, "sodium_mg": 38800.0, "saturated_fat_g": 0.0, "protein_g": 0.0, "fat_g": 0.0, "carbs_g": 0.0, "calories": 0.0, "sugar_g": 0.0}, "basis": "initial_edible_formula_grams"}], "source_url": "https://fdc.nal.usda.gov/"}, "prep_time_minutes": 20, "cook_time_minutes": 40, "total_time_minutes": 105, "course": "Desserts", "summary": "Karottenkuchen mit Zimt aus einer 20 cmForm, ohne Glasur. Acht Stücke, abgewogene Zutaten und eingeplante Abkühlzeit.", "content_html": "<p>Karottenkuchen mit Zimt aus einer 20 cmForm, ohne Glasur. Acht Stücke, abgewogene Zutaten und eingeplante Abkühlzeit.</p>", "keywords": ["Karottenkuchen ohne Glasur"], "gallery": [{"url": "/recetas/receta-torta-de-zanahoria/portada.webp", "alt": "Karottenkuchen ohne Glasur"}], "published": true, "editorial_status": "published"}, {"id": "bc488203-7d33-57e6-b309-9b49e62afa30", "recipe_group_id": "de2ec78c-3533-49db-92f0-db85d9884015", "language": "en", "slug": "carrot-cake-recipe", "public_path": "/en/carrot-cake-recipe", "source_url": "https://manualdecocina.com/en/carrot-cake-recipe/", "title": "Carrot cake without frosting", "excerpt": "Cinnamon carrot cake baked in a 20 cm round tin and served without frosting. Eight slices, weighed ingredients and cooling time included.", "category": "Desserts", "category_slug": "postres", "cuisine": "Home cooking", "difficulty": "Medium", "servings": 8, "image_url": "/recetas/receta-torta-de-zanahoria/portada.webp", "ingredients": [{"amount": 250, "unit": "g", "name": "peeled carrots", "group": "Ingredients"}, {"amount": 200, "unit": "g", "name": "plain wheat flour", "group": "Ingredients"}, {"amount": 160, "unit": "g", "name": "white sugar", "group": "Ingredients"}, {"amount": 120, "unit": "g", "name": "raw egg without shell", "group": "Ingredients"}, {"amount": 100, "unit": "g", "name": "canola oil", "group": "Ingredients"}, {"amount": 8, "unit": "g", "name": "baking powder", "group": "Ingredients"}, {"amount": 3, "unit": "g", "name": "ground cinnamon", "group": "Ingredients"}, {"amount": 1, "unit": "g", "name": "fine salt", "group": "Ingredients"}], "steps": [{"title": "Prepare the tin and weigh", "content": "Preheat the conventional oven to 175 °C. Line the base and sides of a 20 cm round tin with baking parchment. Weigh all ingredients:120 g egg without shell and 250 g carrots after peeling. Do not oil the tin; it is already lined.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-01.webp", "image_alt": "Carrot cake without frosting: Prepare the tin and weigh"}, {"title": "Mix the dry ingredients", "content": "Sift 200 g flour and 8 g baking powder together into a bowl. Add 3 g ground cinnamon and 1 g salt. Stir to distribute the raising agent, avoiding concentrated pockets and uneven rising. Set this dry mixture aside.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-02.webp", "image_alt": "Carrot cake without frosting: Mix the dry ingredients"}, {"title": "Whisk egg, sugar and oil", "content": "Whisk 120 g egg with 160 g sugar for 2 minutes until combined. Pour in 100 g canola oil in a thin stream while stirring. There is no need to whip the eggs or double their volume: aim for a uniform mixture without separated oil.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-03.webp", "image_alt": "Carrot cake without frosting: Whisk egg, sugar and oil"}, {"title": "Grate the carrots", "content": "Finely grate 250 g peeled carrots and fold into the wet mixture with a spatula. Keep their natural moisture without squeezing. Coarse pieces take longer to soften and change the intended texture.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-04.webp", "image_alt": "Carrot cake without frosting: Grate the carrots"}, {"title": "Fold in the flour", "content": "Add the dry mixture in two batches. Lift batter from the bottom with a spatula while turning the bowl, just until no pockets of flour remain. Do not beat for a long time after adding flour. The batter will be thick and moist, with visible carrots.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-05.webp", "image_alt": "Carrot cake without frosting: Fold in the flour"}, {"title": "Fill the tin", "content": "Transfer all the batter to the lined tin and gently level the surface. Tap the tin lightly once on a cloth to remove large air pockets. Place immediately on the middle oven shelf; do not rest the batter before baking.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-06.webp", "image_alt": "Carrot cake without frosting: Fill the tin"}, {"title": "Bake and check the centre", "content": "Bake about 40 minutes at 175 °C. Check from minute 35: a skewer inserted into the centre should come out without liquid batter, though moist crumbs are fine. If batter remains, bake another 5 minutes and check again. Do not rely on exterior colour alone; include extra baking time.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-07.webp", "image_alt": "Carrot cake without frosting: Bake and check the centre"}, {"title": "Cool, unmould and serve", "content": "Leave in the tin for 15 minutes. Unmould onto a rack, remove parchment and wait another 30 minutes before cutting into eight slices. Serve without frosting, nuts or sides. The planned 105 minutes include 45 cooling; add any extra baking or cooling needed.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-08.webp", "image_alt": "Carrot cake without frosting: Cool, unmould and serve"}], "notes": "Original proposed formula, not yet kitchen tested. Contains wheat and egg. Egg weight excludes shells. No frosting or nuts included. Different flour or tin changes the result and baking time. Store the cooled cake in a closed container; refrigerate if it will not be eaten soon, and let individual slices come to room temperature before serving.", "seo": {"title": "Carrot cake without frosting: step-by-step recipe", "description": "Cinnamon carrot cake baked in a 20 cm round tin and served without frosting. Eight slices, weighed ingredients and cooling time included.", "about": "Cinnamon carrot cake baked in a 20 cm round tin and served without frosting. Eight slices, weighed ingredients and cooling time included.", "faq": [{"q": "Does it have cream cheese frosting?", "a": "No. Adding frosting changes ingredients, time and nutrition."}, {"q": "Can I use a smaller tin?", "a": "The batter will be deeper and need different timing. The reference is 20 cm; always check the centre."}, {"q": "Why are the carrots not squeezed?", "a": "The formula includes their natural moisture. Squeezing changes the liquid-to-flour balance."}], "image_alt": "Carrot cake without frosting", "image_variants": ["/recetas/receta-torta-de-zanahoria/portada-1x1.webp", "/recetas/receta-torta-de-zanahoria/portada-4x3.webp", "/recetas/receta-torta-de-zanahoria/portada-16x9.webp"]}, "nutrition": {"calories": 314.6, "protein_g": 4.8, "carbs_g": 42.7, "fat_g": 14.3, "saturated_fat_g": 1.4, "fiber_g": 1.8, "sugar_g": 21.6, "sodium_mg": 171.0, "serving_size": "One of 8 equal servings", "estimated": true, "source": "USDA FoodData Central — SR Legacy (2018)", "method": "Sum of edible starting grams × USDA nutrients per 100 g, divided by 8. No unmeasured cooking losses applied. The full formula is divided into eight equal slices. Frosting, nuts and sides are not included.", "note": "Estimate, not a laboratory analysis or kitchen test. Brands, leftovers and cooked yield can vary. The full formula is divided into eight equal slices. Frosting, nuts and sides are not included.", "inputs": [{"fdc_id": 170393, "description": "Carrots, raw", "recipe_grams": 250, "edible_grams": 250, "per_100g": {"saturated_fat_g": 0.032, "sodium_mg": 69.0, "protein_g": 0.93, "fat_g": 0.24, "sugar_g": 4.74, "carbs_g": 9.58, "calories": 41.0, "fiber_g": 2.8}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 169761, "description": "Wheat flour, white, all-purpose, unenriched", "recipe_grams": 200, "edible_grams": 200, "per_100g": {"fat_g": 0.98, "carbs_g": 76.3, "calories": 364, "fiber_g": 2.7, "sodium_mg": 2.0, "protein_g": 10.3, "saturated_fat_g": 0.155, "sugar_g": 0.27}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 169655, "description": "Sugars, granulated", "recipe_grams": 160, "edible_grams": 160, "per_100g": {"protein_g": 0.0, "sodium_mg": 1.0, "fat_g": 0.0, "calories": 387, "saturated_fat_g": 0.0, "sugar_g": 99.8, "carbs_g": 100, "fiber_g": 0.0}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 171287, "description": "Egg, whole, raw, fresh", "recipe_grams": 120, "edible_grams": 120, "per_100g": {"calories": 143, "saturated_fat_g": 3.13, "protein_g": 12.6, "sodium_mg": 142, "sugar_g": 0.37, "fat_g": 9.51, "carbs_g": 0.72, "fiber_g": 0.0}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 172336, "description": "Oil, canola", "recipe_grams": 100, "edible_grams": 100, "per_100g": {"fat_g": 100, "saturated_fat_g": 7.36, "protein_g": 0.0, "carbs_g": 0.0, "calories": 884, "fiber_g": 0.0, "sodium_mg": 0.0, "sugar_g": 0.0}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 172804, "description": "Leavening agents, baking powder, double-acting, straight phosphate", "recipe_grams": 8, "edible_grams": 8, "per_100g": {"saturated_fat_g": 0.0, "fiber_g": 0.2, "fat_g": 0.0, "carbs_g": 24.1, "calories": 51.0, "protein_g": 0.1, "sodium_mg": 7890.0, "sugar_g": 0.0}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 171320, "description": "Spices, cinnamon, ground", "recipe_grams": 3, "edible_grams": 3, "per_100g": {"sugar_g": 2.17, "fiber_g": 53.1, "protein_g": 3.99, "sodium_mg": 10.0, "saturated_fat_g": 0.345, "fat_g": 1.24, "carbs_g": 80.6, "calories": 247}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 173468, "description": "Salt, table", "recipe_grams": 1, "edible_grams": 1, "per_100g": {"fiber_g": 0.0, "sodium_mg": 38800.0, "saturated_fat_g": 0.0, "protein_g": 0.0, "fat_g": 0.0, "carbs_g": 0.0, "calories": 0.0, "sugar_g": 0.0}, "basis": "initial_edible_formula_grams"}], "source_url": "https://fdc.nal.usda.gov/"}, "prep_time_minutes": 20, "cook_time_minutes": 40, "total_time_minutes": 105, "course": "Desserts", "summary": "Cinnamon carrot cake baked in a 20 cm round tin and served without frosting. Eight slices, weighed ingredients and cooling time included.", "content_html": "<p>Cinnamon carrot cake baked in a 20 cm round tin and served without frosting. Eight slices, weighed ingredients and cooling time included.</p>", "keywords": ["Carrot cake without frosting"], "gallery": [{"url": "/recetas/receta-torta-de-zanahoria/portada.webp", "alt": "Carrot cake without frosting"}], "published": true, "editorial_status": "published"}, {"id": "e499ea93-ab5e-5b86-9ff6-2e6074ea0680", "recipe_group_id": "de2ec78c-3533-49db-92f0-db85d9884015", "language": "fr", "slug": "gateau-aux-carottes", "public_path": "/fr/gateau-aux-carottes", "source_url": null, "title": "Gâteau aux carottes sans glaçage", "excerpt": "Gâteau aux carottes et à la cannelle dans un moule de 20 cm, sans glaçage. Huit parts, ingrédients pesés et refroidissement inclus.", "category": "Desserts", "category_slug": "postres", "cuisine": "Cuisine familiale", "difficulty": "Moyenne", "servings": 8, "image_url": "/recetas/receta-torta-de-zanahoria/portada.webp", "ingredients": [{"amount": 250, "unit": "g", "name": "carottes épluchées", "group": "Ingrédients"}, {"amount": 200, "unit": "g", "name": "farine de blé ordinaire", "group": "Ingrédients"}, {"amount": 160, "unit": "g", "name": "sucre blanc", "group": "Ingrédients"}, {"amount": 120, "unit": "g", "name": "œuf cru sans coquille", "group": "Ingrédients"}, {"amount": 100, "unit": "g", "name": "huile de colza", "group": "Ingrédients"}, {"amount": 8, "unit": "g", "name": "levure chimique", "group": "Ingrédients"}, {"amount": 3, "unit": "g", "name": "cannelle moulue", "group": "Ingrédients"}, {"amount": 1, "unit": "g", "name": "sel fin", "group": "Ingrédients"}], "steps": [{"title": "Préparez le moule et pesez", "content": "Préchauffez le four traditionnel à 175 °C. Tapissez le fond et les parois d’un moule rond de 20 cm de papier cuisson. Pesez tous les ingrédients :120 g d’œuf sans coquille et 250 g de carottes après épluchage. N’ajoutez pas d’huile au moule déjà tapissé.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-01.webp", "image_alt": "Gâteau aux carottes sans glaçage: Préparez le moule et pesez"}, {"title": "Mélangez les ingrédients secs", "content": "Tamisez ensemble 200 g de farine et 8 g de levure chimique dans un bol. Ajoutez 3 g de cannelle et 1 g de sel. Remuez pour bien répartir la levure, éviter les zones concentrées et une levée irrégulière. Réservez ce mélange sec.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-02.webp", "image_alt": "Gâteau aux carottes sans glaçage: Mélangez les ingrédients secs"}, {"title": "Battez œuf, sucre et huile", "content": "Battez 120 g d’œuf avec 160 g de sucre pendant 2 minutes. Versez 100 g d’huile de colza en filet en remuant. Inutile de monter les œufs ou de doubler leur volume : cherchez un mélange homogène sans huile séparée.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-03.webp", "image_alt": "Gâteau aux carottes sans glaçage: Battez œuf, sucre et huile"}, {"title": "Râpez les carottes", "content": "Râpez finement 250 g de carottes épluchées et incorporez-les aux liquides à la spatule. Gardez leur humidité naturelle sans les essorer. De gros morceaux mettraient davantage de temps à s’attendrir et modifieraient la texture prévue.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-04.webp", "image_alt": "Gâteau aux carottes sans glaçage: Râpez les carottes"}, {"title": "Incorporez la farine", "content": "Ajoutez le mélange sec en deux fois. Soulevez la pâte depuis le fond à la spatule en tournant le bol, juste jusqu’à disparition des poches de farine. Ne battez pas longuement après son ajout. La pâte sera épaisse, humide, avec des carottes visibles.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-05.webp", "image_alt": "Gâteau aux carottes sans glaçage: Incorporez la farine"}, {"title": "Remplissez le moule", "content": "Versez toute la pâte dans le moule et égalisez doucement. Tapez légèrement une fois le moule sur un torchon pour éliminer les grosses bulles d’air. Enfournez immédiatement au centre ; ne laissez pas reposer la pâte avant cuisson.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-06.webp", "image_alt": "Gâteau aux carottes sans glaçage: Remplissez le moule"}, {"title": "Cuisez et vérifiez le centre", "content": "Cuisez environ 40 minutes à 175 °C. Vérifiez dès 35 minutes : une pique au centre doit ressortir sans pâte liquide, mais peut porter des miettes humides. Si de la pâte reste, poursuivez 5 minutes et vérifiez encore. La couleur extérieure seule ne suffit pas ; ajoutez le temps supplémentaire.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-07.webp", "image_alt": "Gâteau aux carottes sans glaçage: Cuisez et vérifiez le centre"}, {"title": "Refroidissez, démoulez et servez", "content": "Attendez 15 minutes dans le moule. Démoulez sur une grille, retirez le papier et attendez encore 30 minutes avant de couper en huit parts. Servez sans glaçage, noix ni accompagnement. Les 105 minutes prévues incluent 45 de refroidissement ; ajoutez toute prolongation nécessaire.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-08.webp", "image_alt": "Gâteau aux carottes sans glaçage: Refroidissez, démoulez et servez"}], "notes": "Formule originale proposée, pas encore testée en cuisine. Contient blé et œuf. Poids d’œuf sans coquille. Aucun glaçage ni noix inclus. Une autre farine ou un autre moule change le résultat et le temps. Conservez le gâteau refroidi dans un récipient fermé ; réfrigérez s’il ne sera pas consommé rapidement et tempérez la part avant de servir.", "seo": {"title": "Gâteau aux carottes sans glaçage: recette étape par étape", "description": "Gâteau aux carottes et à la cannelle dans un moule de 20 cm, sans glaçage. Huit parts, ingrédients pesés et refroidissement inclus.", "about": "Gâteau aux carottes et à la cannelle dans un moule de 20 cm, sans glaçage. Huit parts, ingrédients pesés et refroidissement inclus.", "faq": [{"q": "Y a-t-il un glaçage au fromage frais ?", "a": "Non. En ajouter change les ingrédients, le temps et la nutrition."}, {"q": "Puis-je utiliser un moule plus petit ?", "a": "La pâte sera plus haute et demandera un autre temps. La référence est 20 cm ; vérifiez toujours le centre."}, {"q": "Pourquoi ne pas essorer les carottes ?", "a": "La formule tient compte de leur humidité naturelle. Les essorer modifie l’équilibre entre liquide et farine."}], "image_alt": "Gâteau aux carottes sans glaçage", "image_variants": ["/recetas/receta-torta-de-zanahoria/portada-1x1.webp", "/recetas/receta-torta-de-zanahoria/portada-4x3.webp", "/recetas/receta-torta-de-zanahoria/portada-16x9.webp"]}, "nutrition": {"calories": 314.6, "protein_g": 4.8, "carbs_g": 42.7, "fat_g": 14.3, "saturated_fat_g": 1.4, "fiber_g": 1.8, "sugar_g": 21.6, "sodium_mg": 171.0, "serving_size": "Une des 8 portions égales", "estimated": true, "source": "USDA FoodData Central — SR Legacy (2018)", "method": "Somme des poids comestibles initiaux en grammes × nutriments USDA pour 100 g, divisée par 8. Aucune perte de cuisson non mesurée appliquée. Toute la formule est répartie en huit parts égales. Glaçage, noix et accompagnements exclus.", "note": "Estimation, pas une analyse de laboratoire ni un essai en cuisine. Marques, restes et rendement peuvent varier. Toute la formule est répartie en huit parts égales. Glaçage, noix et accompagnements exclus.", "inputs": [{"fdc_id": 170393, "description": "Carrots, raw", "recipe_grams": 250, "edible_grams": 250, "per_100g": {"saturated_fat_g": 0.032, "sodium_mg": 69.0, "protein_g": 0.93, "fat_g": 0.24, "sugar_g": 4.74, "carbs_g": 9.58, "calories": 41.0, "fiber_g": 2.8}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 169761, "description": "Wheat flour, white, all-purpose, unenriched", "recipe_grams": 200, "edible_grams": 200, "per_100g": {"fat_g": 0.98, "carbs_g": 76.3, "calories": 364, "fiber_g": 2.7, "sodium_mg": 2.0, "protein_g": 10.3, "saturated_fat_g": 0.155, "sugar_g": 0.27}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 169655, "description": "Sugars, granulated", "recipe_grams": 160, "edible_grams": 160, "per_100g": {"protein_g": 0.0, "sodium_mg": 1.0, "fat_g": 0.0, "calories": 387, "saturated_fat_g": 0.0, "sugar_g": 99.8, "carbs_g": 100, "fiber_g": 0.0}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 171287, "description": "Egg, whole, raw, fresh", "recipe_grams": 120, "edible_grams": 120, "per_100g": {"calories": 143, "saturated_fat_g": 3.13, "protein_g": 12.6, "sodium_mg": 142, "sugar_g": 0.37, "fat_g": 9.51, "carbs_g": 0.72, "fiber_g": 0.0}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 172336, "description": "Oil, canola", "recipe_grams": 100, "edible_grams": 100, "per_100g": {"fat_g": 100, "saturated_fat_g": 7.36, "protein_g": 0.0, "carbs_g": 0.0, "calories": 884, "fiber_g": 0.0, "sodium_mg": 0.0, "sugar_g": 0.0}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 172804, "description": "Leavening agents, baking powder, double-acting, straight phosphate", "recipe_grams": 8, "edible_grams": 8, "per_100g": {"saturated_fat_g": 0.0, "fiber_g": 0.2, "fat_g": 0.0, "carbs_g": 24.1, "calories": 51.0, "protein_g": 0.1, "sodium_mg": 7890.0, "sugar_g": 0.0}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 171320, "description": "Spices, cinnamon, ground", "recipe_grams": 3, "edible_grams": 3, "per_100g": {"sugar_g": 2.17, "fiber_g": 53.1, "protein_g": 3.99, "sodium_mg": 10.0, "saturated_fat_g": 0.345, "fat_g": 1.24, "carbs_g": 80.6, "calories": 247}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 173468, "description": "Salt, table", "recipe_grams": 1, "edible_grams": 1, "per_100g": {"fiber_g": 0.0, "sodium_mg": 38800.0, "saturated_fat_g": 0.0, "protein_g": 0.0, "fat_g": 0.0, "carbs_g": 0.0, "calories": 0.0, "sugar_g": 0.0}, "basis": "initial_edible_formula_grams"}], "source_url": "https://fdc.nal.usda.gov/"}, "prep_time_minutes": 20, "cook_time_minutes": 40, "total_time_minutes": 105, "course": "Desserts", "summary": "Gâteau aux carottes et à la cannelle dans un moule de 20 cm, sans glaçage. Huit parts, ingrédients pesés et refroidissement inclus.", "content_html": "<p>Gâteau aux carottes et à la cannelle dans un moule de 20 cm, sans glaçage. Huit parts, ingrédients pesés et refroidissement inclus.</p>", "keywords": ["Gâteau aux carottes sans glaçage"], "gallery": [{"url": "/recetas/receta-torta-de-zanahoria/portada.webp", "alt": "Gâteau aux carottes sans glaçage"}], "published": true, "editorial_status": "published"}, {"id": "d180c12c-dd1d-510d-afcc-7f7a56949607", "recipe_group_id": "de2ec78c-3533-49db-92f0-db85d9884015", "language": "it", "slug": "torta-di-carote", "public_path": "/it/torta-di-carote", "source_url": null, "title": "Torta di carote senza copertura", "excerpt": "Torta di carote e cannella in uno stampo da 20 cm, senza copertura. Otto porzioni, ingredienti pesati e raffreddamento incluso.", "category": "Dolci", "category_slug": "postres", "cuisine": "Cucina casalinga", "difficulty": "Media", "servings": 8, "image_url": "/recetas/receta-torta-de-zanahoria/portada.webp", "ingredients": [{"amount": 250, "unit": "g", "name": "carote pelate", "group": "Ingredienti"}, {"amount": 200, "unit": "g", "name": "farina di frumento comune", "group": "Ingredienti"}, {"amount": 160, "unit": "g", "name": "zucchero bianco", "group": "Ingredienti"}, {"amount": 120, "unit": "g", "name": "uovo crudo senza guscio", "group": "Ingredienti"}, {"amount": 100, "unit": "g", "name": "olio di canola", "group": "Ingredienti"}, {"amount": 8, "unit": "g", "name": "lievito per dolci", "group": "Ingredienti"}, {"amount": 3, "unit": "g", "name": "cannella macinata", "group": "Ingredienti"}, {"amount": 1, "unit": "g", "name": "sale fino", "group": "Ingredienti"}], "steps": [{"title": "Prepara lo stampo e pesa", "content": "Preriscalda il forno statico a 175 °C. Rivesti fondo e pareti di uno stampo rotondo da 20 cm con carta forno. Pesa tutti gli ingredienti:120 g di uovo senza guscio e 250 g di carote già pelate. Non ungere lo stampo: è già rivestito.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-01.webp", "image_alt": "Torta di carote senza copertura: Prepara lo stampo e pesa"}, {"title": "Mescola gli ingredienti secchi", "content": "Setaccia insieme 200 g di farina e 8 g di lievito in una ciotola. Aggiungi 3 g di cannella e 1 g di sale. Mescola per distribuire il lievito, evitando zone concentrate e una crescita irregolare. Metti da parte il composto secco.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-02.webp", "image_alt": "Torta di carote senza copertura: Mescola gli ingredienti secchi"}, {"title": "Sbatti uovo, zucchero e olio", "content": "Sbatti 120 g di uovo con 160 g di zucchero per 2 minuti. Versa 100 g di olio a filo mentre mescoli. Non occorre montare le uova o raddoppiarne il volume: cerca un composto uniforme senza olio separato.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-03.webp", "image_alt": "Torta di carote senza copertura: Sbatti uovo, zucchero e olio"}, {"title": "Grattugia le carote", "content": "Grattugia finemente 250 g di carote pelate e incorporale ai liquidi con una spatola. Conserva l’umidità naturale, senza strizzarle. Pezzi grossi richiedono più tempo per ammorbidirsi e modificano la consistenza prevista.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-04.webp", "image_alt": "Torta di carote senza copertura: Grattugia le carote"}, {"title": "Incorpora la farina", "content": "Aggiungi il composto secco in due volte. Solleva l’impasto dal fondo con la spatola girando la ciotola, solo finché non restano sacche di farina. Non sbattere a lungo dopo l’aggiunta. L’impasto sarà denso e umido, con carote visibili.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-05.webp", "image_alt": "Torta di carote senza copertura: Incorpora la farina"}, {"title": "Riempi lo stampo", "content": "Versa tutto l’impasto nello stampo e livella delicatamente. Batti leggermente una volta lo stampo sopra un panno per eliminare grandi bolle d’aria. Inforna subito al centro; non lasciare riposare l’impasto prima della cottura.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-06.webp", "image_alt": "Torta di carote senza copertura: Riempi lo stampo"}, {"title": "Cuoci e controlla il centro", "content": "Cuoci circa 40 minuti a 175 °C. Controlla dal minuto 35: uno stecchino al centro deve uscire senza impasto liquido, anche se può avere briciole umide. Se resta impasto, cuoci altri 5 minuti e ripeti. Non giudicare solo dal colore esterno; aggiungi il tempo supplementare.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-07.webp", "image_alt": "Torta di carote senza copertura: Cuoci e controlla il centro"}, {"title": "Raffredda, sforma e servi", "content": "Lascia 15 minuti nello stampo. Sforma su una griglia, togli la carta e attendi altri 30 minuti prima di tagliare otto porzioni. Servi senza copertura, frutta secca o contorno. I 105 minuti previsti comprendono 45 di raffreddamento; aggiungi eventuali prolungamenti.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-08.webp", "image_alt": "Torta di carote senza copertura: Raffredda, sforma e servi"}], "notes": "Formula originale proposta, non ancora testata in cucina. Contiene frumento e uovo. Peso dell’uovo senza guscio. Non include copertura o frutta secca. Farine o stampi diversi modificano risultato e tempo. Conserva la torta fredda in un contenitore chiuso; refrigerala se non sarà consumata presto e lascia temperare la porzione prima di servire.", "seo": {"title": "Torta di carote senza copertura: ricetta passo passo", "description": "Torta di carote e cannella in uno stampo da 20 cm, senza copertura. Otto porzioni, ingredienti pesati e raffreddamento incluso.", "about": "Torta di carote e cannella in uno stampo da 20 cm, senza copertura. Otto porzioni, ingredienti pesati e raffreddamento incluso.", "faq": [{"q": "Ha una copertura al formaggio?", "a": "No. Aggiungerla cambia ingredienti, tempo e valori nutrizionali."}, {"q": "Posso usare uno stampo più piccolo?", "a": "L’impasto sarà più alto e richiederà un tempo diverso. Il riferimento è 20 cm; controlla sempre il centro."}, {"q": "Perché non si strizzano le carote?", "a": "La formula considera la loro umidità naturale. Strizzarle cambia l’equilibrio tra liquidi e farina."}], "image_alt": "Torta di carote senza copertura", "image_variants": ["/recetas/receta-torta-de-zanahoria/portada-1x1.webp", "/recetas/receta-torta-de-zanahoria/portada-4x3.webp", "/recetas/receta-torta-de-zanahoria/portada-16x9.webp"]}, "nutrition": {"calories": 314.6, "protein_g": 4.8, "carbs_g": 42.7, "fat_g": 14.3, "saturated_fat_g": 1.4, "fiber_g": 1.8, "sugar_g": 21.6, "sodium_mg": 171.0, "serving_size": "Una delle 8 porzioni uguali", "estimated": true, "source": "USDA FoodData Central — SR Legacy (2018)", "method": "Somma dei grammi comestibili iniziali × nutrienti USDA per 100 g, divisa per 8. Nessuna perdita di cottura non misurata applicata. La formula intera viene divisa in otto porzioni uguali. Non include copertura, frutta secca o contorni.", "note": "Stima, non analisi di laboratorio né prova in cucina. Marche, residui e resa possono variare. La formula intera viene divisa in otto porzioni uguali. Non include copertura, frutta secca o contorni.", "inputs": [{"fdc_id": 170393, "description": "Carrots, raw", "recipe_grams": 250, "edible_grams": 250, "per_100g": {"saturated_fat_g": 0.032, "sodium_mg": 69.0, "protein_g": 0.93, "fat_g": 0.24, "sugar_g": 4.74, "carbs_g": 9.58, "calories": 41.0, "fiber_g": 2.8}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 169761, "description": "Wheat flour, white, all-purpose, unenriched", "recipe_grams": 200, "edible_grams": 200, "per_100g": {"fat_g": 0.98, "carbs_g": 76.3, "calories": 364, "fiber_g": 2.7, "sodium_mg": 2.0, "protein_g": 10.3, "saturated_fat_g": 0.155, "sugar_g": 0.27}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 169655, "description": "Sugars, granulated", "recipe_grams": 160, "edible_grams": 160, "per_100g": {"protein_g": 0.0, "sodium_mg": 1.0, "fat_g": 0.0, "calories": 387, "saturated_fat_g": 0.0, "sugar_g": 99.8, "carbs_g": 100, "fiber_g": 0.0}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 171287, "description": "Egg, whole, raw, fresh", "recipe_grams": 120, "edible_grams": 120, "per_100g": {"calories": 143, "saturated_fat_g": 3.13, "protein_g": 12.6, "sodium_mg": 142, "sugar_g": 0.37, "fat_g": 9.51, "carbs_g": 0.72, "fiber_g": 0.0}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 172336, "description": "Oil, canola", "recipe_grams": 100, "edible_grams": 100, "per_100g": {"fat_g": 100, "saturated_fat_g": 7.36, "protein_g": 0.0, "carbs_g": 0.0, "calories": 884, "fiber_g": 0.0, "sodium_mg": 0.0, "sugar_g": 0.0}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 172804, "description": "Leavening agents, baking powder, double-acting, straight phosphate", "recipe_grams": 8, "edible_grams": 8, "per_100g": {"saturated_fat_g": 0.0, "fiber_g": 0.2, "fat_g": 0.0, "carbs_g": 24.1, "calories": 51.0, "protein_g": 0.1, "sodium_mg": 7890.0, "sugar_g": 0.0}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 171320, "description": "Spices, cinnamon, ground", "recipe_grams": 3, "edible_grams": 3, "per_100g": {"sugar_g": 2.17, "fiber_g": 53.1, "protein_g": 3.99, "sodium_mg": 10.0, "saturated_fat_g": 0.345, "fat_g": 1.24, "carbs_g": 80.6, "calories": 247}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 173468, "description": "Salt, table", "recipe_grams": 1, "edible_grams": 1, "per_100g": {"fiber_g": 0.0, "sodium_mg": 38800.0, "saturated_fat_g": 0.0, "protein_g": 0.0, "fat_g": 0.0, "carbs_g": 0.0, "calories": 0.0, "sugar_g": 0.0}, "basis": "initial_edible_formula_grams"}], "source_url": "https://fdc.nal.usda.gov/"}, "prep_time_minutes": 20, "cook_time_minutes": 40, "total_time_minutes": 105, "course": "Dolci", "summary": "Torta di carote e cannella in uno stampo da 20 cm, senza copertura. Otto porzioni, ingredienti pesati e raffreddamento incluso.", "content_html": "<p>Torta di carote e cannella in uno stampo da 20 cm, senza copertura. Otto porzioni, ingredienti pesati e raffreddamento incluso.</p>", "keywords": ["Torta di carote senza copertura"], "gallery": [{"url": "/recetas/receta-torta-de-zanahoria/portada.webp", "alt": "Torta di carote senza copertura"}], "published": true, "editorial_status": "published"}, {"id": "e085e124-5a74-5e5c-a51d-eb8d3898448f", "recipe_group_id": "de2ec78c-3533-49db-92f0-db85d9884015", "language": "ja", "slug": "キャロットケーキ", "public_path": "/ja/キャロットケーキ", "source_url": null, "title": "フロスティングなしのキャロットケーキ", "excerpt": "直径20 cm型で焼くシナモン風味のキャロットケーキ。8切れ分で、材料の計量と冷ます時間を含みます。", "category": "デザート", "category_slug": "postres", "cuisine": "家庭料理", "difficulty": "普通", "servings": 8, "image_url": "/recetas/receta-torta-de-zanahoria/portada.webp", "ingredients": [{"amount": 250, "unit": "g", "name": "皮をむいたにんじん", "group": "材料"}, {"amount": 200, "unit": "g", "name": "普通小麦粉", "group": "材料"}, {"amount": 160, "unit": "g", "name": "白砂糖", "group": "材料"}, {"amount": 120, "unit": "g", "name": "生卵（殻なし）", "group": "材料"}, {"amount": 100, "unit": "g", "name": "キャノーラ油", "group": "材料"}, {"amount": 8, "unit": "g", "name": "ベーキングパウダー", "group": "材料"}, {"amount": 3, "unit": "g", "name": "シナモン（粉）", "group": "材料"}, {"amount": 1, "unit": "g", "name": "細粒の塩", "group": "材料"}], "steps": [{"title": "型を準備して量る", "content": "上下加熱のオーブンを175 °Cに予熱します。直径20 cmの丸型の底と側面にオーブン用シートを敷きます。すべての材料を量り、卵120 gは殻なし、にんじん250 gは皮をむいた後の重量にします。型にはシートがあるため油を追加しません。", "image_url": "/recetas/receta-torta-de-zanahoria/paso-01.webp", "image_alt": "フロスティングなしのキャロットケーキ: 型を準備して量る"}, {"title": "粉類を混ぜる", "content": "小麦粉200 gとベーキングパウダー8 gを一緒にふるってボウルに入れます。シナモン3 gと塩1 gを加えて混ぜ、膨張剤を均一にします。味が集中したり、膨らみが不均一になったりしないようにし、この粉の混合物を取り置きます。", "image_url": "/recetas/receta-torta-de-zanahoria/paso-02.webp", "image_alt": "フロスティングなしのキャロットケーキ: 粉類を混ぜる"}, {"title": "卵、砂糖、油を混ぜる", "content": "卵120 gと砂糖160 gを2分混ぜます。混ぜ続けながらキャノーラ油100 gを細く注ぎます。卵を泡立てたり、体積を倍にしたりする必要はありません。油が分離しない均一な状態を目指します。", "image_url": "/recetas/receta-torta-de-zanahoria/paso-03.webp", "image_alt": "フロスティングなしのキャロットケーキ: 卵、砂糖、油を混ぜる"}, {"title": "にんじんを細かくおろす", "content": "皮をむいたにんじん250 gを細かくおろし、液体に加えてへらで均等に混ぜます。自然な水分を残し、搾りません。粗いかけらは柔らかくなるのに時間がかかり、想定した食感が変わります。", "image_url": "/recetas/receta-torta-de-zanahoria/paso-04.webp", "image_alt": "フロスティングなしのキャロットケーキ: にんじんを細かくおろす"}, {"title": "粉を加える", "content": "粉類を2回に分けて加えます。ボウルを回しながらへらで底から持ち上げ、粉の塊がなくなるまで混ぜます。粉を加えた後は長く泡立てません。生地は濃くしっとりし、にんじんが見える状態になります。", "image_url": "/recetas/receta-torta-de-zanahoria/paso-05.webp", "image_alt": "フロスティングなしのキャロットケーキ: 粉を加える"}, {"title": "型に流す", "content": "生地を全量型に流し、表面を優しくならします。布の上で型を軽く1回たたき、大きな気泡を抜きます。すぐオーブンの中央に入れます。焼く前に生地を休ませません。", "image_url": "/recetas/receta-torta-de-zanahoria/paso-06.webp", "image_alt": "フロスティングなしのキャロットケーキ: 型に流す"}, {"title": "焼いて中央を確認する", "content": "175 °Cで約40分焼きます。35分から中央に竹串を刺して確認し、液状の生地が付かない状態にします。湿ったくずは付いても構いません。生地が付く場合は5分追加し再確認します。外側の色だけで判断せず、追加時間を合計に含めます。", "image_url": "/recetas/receta-torta-de-zanahoria/paso-07.webp", "image_alt": "フロスティングなしのキャロットケーキ: 焼いて中央を確認する"}, {"title": "冷まして型から外し盛る", "content": "型のまま15分置きます。網に外してシートを取り、さらに30分待って8切れに分けます。フロスティング、ナッツ、付け合わせなしで盛ります。予定の105分には冷却45分が含まれます。追加の焼き時間や冷却時間が必要なら加算します。", "image_url": "/recetas/receta-torta-de-zanahoria/paso-08.webp", "image_alt": "フロスティングなしのキャロットケーキ: 冷まして型から外し盛る"}], "notes": "独自のレシピ案で調理試験は未実施です。小麦と卵を含み、卵の重量は殻を除きます。フロスティングやナッツは含みません。粉や型を変えると仕上がりと時間が変わります。冷めたケーキは密閉容器に入れ、すぐ食べない場合は冷蔵し、食べる分を室温に戻してから盛ります。", "seo": {"title": "フロスティングなしのキャロットケーキ: 作り方", "description": "直径20 cm型で焼くシナモン風味のキャロットケーキ。8切れ分で、材料の計量と冷ます時間を含みます。", "about": "直径20 cm型で焼くシナモン風味のキャロットケーキ。8切れ分で、材料の計量と冷ます時間を含みます。", "faq": [{"q": "クリームチーズのフロスティングはありますか？", "a": "ありません。追加すると材料、所要時間、栄養値が変わります。"}, {"q": "小さい型を使えますか？", "a": "生地が厚くなり、焼く時間が変わります。基準は直径20 cmで、中央を必ず確認します。"}, {"q": "にんじんを搾らない理由は？", "a": "自然な水分を配合に含めているためです。搾ると液体と粉の比率が変わります。"}], "image_alt": "フロスティングなしのキャロットケーキ", "image_variants": ["/recetas/receta-torta-de-zanahoria/portada-1x1.webp", "/recetas/receta-torta-de-zanahoria/portada-4x3.webp", "/recetas/receta-torta-de-zanahoria/portada-16x9.webp"]}, "nutrition": {"calories": 314.6, "protein_g": 4.8, "carbs_g": 42.7, "fat_g": 14.3, "saturated_fat_g": 1.4, "fiber_g": 1.8, "sugar_g": 21.6, "sodium_mg": 171.0, "serving_size": "全量の8分の1", "estimated": true, "source": "USDA FoodData Central — SR Legacy (2018)", "method": "可食部の初期重量g × USDAの100 g当たり栄養値を合計し、8人分で割ります。未測定の加熱損失は補正しません。 全配合を8等分した値です。フロスティング、ナッツ、付け合わせは含みません。", "note": "推定値で、実験室分析や調理試験の値ではありません。製品、残量、調理後の収量で変わります。 全配合を8等分した値です。フロスティング、ナッツ、付け合わせは含みません。", "inputs": [{"fdc_id": 170393, "description": "Carrots, raw", "recipe_grams": 250, "edible_grams": 250, "per_100g": {"saturated_fat_g": 0.032, "sodium_mg": 69.0, "protein_g": 0.93, "fat_g": 0.24, "sugar_g": 4.74, "carbs_g": 9.58, "calories": 41.0, "fiber_g": 2.8}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 169761, "description": "Wheat flour, white, all-purpose, unenriched", "recipe_grams": 200, "edible_grams": 200, "per_100g": {"fat_g": 0.98, "carbs_g": 76.3, "calories": 364, "fiber_g": 2.7, "sodium_mg": 2.0, "protein_g": 10.3, "saturated_fat_g": 0.155, "sugar_g": 0.27}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 169655, "description": "Sugars, granulated", "recipe_grams": 160, "edible_grams": 160, "per_100g": {"protein_g": 0.0, "sodium_mg": 1.0, "fat_g": 0.0, "calories": 387, "saturated_fat_g": 0.0, "sugar_g": 99.8, "carbs_g": 100, "fiber_g": 0.0}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 171287, "description": "Egg, whole, raw, fresh", "recipe_grams": 120, "edible_grams": 120, "per_100g": {"calories": 143, "saturated_fat_g": 3.13, "protein_g": 12.6, "sodium_mg": 142, "sugar_g": 0.37, "fat_g": 9.51, "carbs_g": 0.72, "fiber_g": 0.0}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 172336, "description": "Oil, canola", "recipe_grams": 100, "edible_grams": 100, "per_100g": {"fat_g": 100, "saturated_fat_g": 7.36, "protein_g": 0.0, "carbs_g": 0.0, "calories": 884, "fiber_g": 0.0, "sodium_mg": 0.0, "sugar_g": 0.0}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 172804, "description": "Leavening agents, baking powder, double-acting, straight phosphate", "recipe_grams": 8, "edible_grams": 8, "per_100g": {"saturated_fat_g": 0.0, "fiber_g": 0.2, "fat_g": 0.0, "carbs_g": 24.1, "calories": 51.0, "protein_g": 0.1, "sodium_mg": 7890.0, "sugar_g": 0.0}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 171320, "description": "Spices, cinnamon, ground", "recipe_grams": 3, "edible_grams": 3, "per_100g": {"sugar_g": 2.17, "fiber_g": 53.1, "protein_g": 3.99, "sodium_mg": 10.0, "saturated_fat_g": 0.345, "fat_g": 1.24, "carbs_g": 80.6, "calories": 247}, "basis": "initial_edible_formula_grams"}, {"fdc_id": 173468, "description": "Salt, table", "recipe_grams": 1, "edible_grams": 1, "per_100g": {"fiber_g": 0.0, "sodium_mg": 38800.0, "saturated_fat_g": 0.0, "protein_g": 0.0, "fat_g": 0.0, "carbs_g": 0.0, "calories": 0.0, "sugar_g": 0.0}, "basis": "initial_edible_formula_grams"}], "source_url": "https://fdc.nal.usda.gov/"}, "prep_time_minutes": 20, "cook_time_minutes": 40, "total_time_minutes": 105, "course": "デザート", "summary": "直径20 cm型で焼くシナモン風味のキャロットケーキ。8切れ分で、材料の計量と冷ます時間を含みます。", "content_html": "<p>直径20 cm型で焼くシナモン風味のキャロットケーキ。8切れ分で、材料の計量と冷ます時間を含みます。</p>", "keywords": ["フロスティングなしのキャロットケーキ"], "gallery": [{"url": "/recetas/receta-torta-de-zanahoria/portada.webp", "alt": "フロスティングなしのキャロットケーキ"}], "published": true, "editorial_status": "published"}, {"id": "0f591b53-a38f-5df1-ae20-9bcd17f11417", "recipe_group_id": "de2ec78c-3533-49db-92f0-db85d9884015", "language": "pt", "slug": "bolo-de-cenoura-com-especiarias", "public_path": "/pt/bolo-de-cenoura-com-especiarias", "source_url": null, "title": "Bolo de cenoura com canela, sem cobertura", "excerpt": "Bolo de cenoura com canela em forma de 20 cm, servido sem cobertura. Oito fatias, ingredientes pesados e tempo para esfriar incluído.", "category": "Sobremesas", "category_slug": "postres", "cuisine": "Cozinha caseira", "difficulty": "Média", "servings": 8, "image_url": "/recetas/receta-torta-de-zanahoria/portada.webp", "ingredients": [{"amount": 250, "unit": "g", "name": "cenoura descascada", "group": "Ingredientes"}, {"amount": 200, "unit": "g", "name": "farinha de trigo comum", "group": "Ingredientes"}, {"amount": 160, "unit": "g", "name": "açúcar branco", "group": "Ingredientes"}, {"amount": 120, "unit": "g", "name": "ovo cru sem casca", "group": "Ingredientes"}, {"amount": 100, "unit": "g", "name": "óleo de canola", "group": "Ingredientes"}, {"amount": 8, "unit": "g", "name": "fermento químico", "group": "Ingredientes"}, {"amount": 3, "unit": "g", "name": "canela em pó", "group": "Ingredientes"}, {"amount": 1, "unit": "g", "name": "sal fino", "group": "Ingredientes"}], "steps": [{"title": "Prepare a forma e pese", "content": "Preaqueça o forno a 175 °C com calor superior e inferior. Forre fundo e laterais de uma forma redonda de 20 cm com papel próprio para forno. Pese todos os ingredientes:120 g de ovo sem casca e 250 g de cenoura após descascar. Não unte a forma já forrada.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-01.webp", "image_alt": "Bolo de cenoura com canela, sem cobertura: Prepare a forma e pese"}, {"title": "Misture os ingredientes secos", "content": "Peneire juntos 200 g de farinha e 8 g de fermento em uma tigela. Junte 3 g de canela e 1 g de sal. Mexa para distribuir o fermento, evitando pontos concentrados e crescimento desigual. Reserve a mistura seca.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-02.webp", "image_alt": "Bolo de cenoura com canela, sem cobertura: Misture os ingredientes secos"}, {"title": "Bata ovo, açúcar e óleo", "content": "Bata 120 g de ovo com 160 g de açúcar por 2 minutos. Acrescente 100 g de óleo de canola em fio, mexendo. Não precisa montar os ovos nem dobrar o volume: procure uma mistura uniforme, sem óleo separado.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-03.webp", "image_alt": "Bolo de cenoura com canela, sem cobertura: Bata ovo, açúcar e óleo"}, {"title": "Rale a cenoura", "content": "Rale finamente 250 g de cenoura descascada e incorpore aos líquidos com espátula. Mantenha a umidade natural, sem espremer. Pedaços grossos demoram mais a amolecer e mudam a textura prevista.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-04.webp", "image_alt": "Bolo de cenoura com canela, sem cobertura: Rale a cenoura"}, {"title": "Incorpore a farinha", "content": "Acrescente os secos em duas vezes. Levante a massa desde o fundo com espátula enquanto gira a tigela, apenas até desaparecerem bolsões de farinha. Não bata por muito tempo depois da adição. A massa ficará espessa e úmida, com cenoura visível.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-05.webp", "image_alt": "Bolo de cenoura com canela, sem cobertura: Incorpore a farinha"}, {"title": "Encha a forma", "content": "Despeje toda a massa na forma e nivele delicadamente. Bata a forma uma vez de leve sobre um pano para retirar bolhas grandes. Leve imediatamente ao centro do forno; não deixe a massa descansar antes de assar.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-06.webp", "image_alt": "Bolo de cenoura com canela, sem cobertura: Encha a forma"}, {"title": "Asse e confira o centro", "content": "Asse cerca de 40 minutos a 175 °C. Confira a partir de 35 minutos: um palito no centro deve sair sem massa líquida, embora possa ter migalhas úmidas. Se sair massa, asse mais 5 minutos e repita. Não avalie apenas pela cor externa; acrescente o tempo adicional.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-07.webp", "image_alt": "Bolo de cenoura com canela, sem cobertura: Asse e confira o centro"}, {"title": "Esfrie, desenforme e sirva", "content": "Deixe 15 minutos na forma. Desenforme sobre grade, retire o papel e espere mais 30 minutos antes de cortar oito fatias. Sirva sem cobertura, castanhas ou acompanhamento. Os 105 minutos previstos incluem 45 para esfriar; acrescente qualquer tempo extra de forno ou resfriamento.", "image_url": "/recetas/receta-torta-de-zanahoria/paso-08.webp", "image_alt": "Bolo de cenoura com canela, sem cobertura: Esfrie, desenforme e sirva"}], "notes": "Fórmula original proposta, ainda sem teste de cozinha. Contém trigo e ovo. O peso do ovo exclui a casca. Não inclui cobertura nem castanhas. Outra farinha ou forma altera resultado e tempo. Guarde o bolo frio em recipiente fechado; refrigere se não for consumir logo e deixe a fatia chegar à temperatura ambiente antes de servir.", "seo": {"title": "Bolo de cenoura com canela, sem cobertura: receita passo a passo", "description": "Bolo de cenoura com canela em forma de 20 cm, servido sem cobertura. Oito fatias, ingredientes pesados e tempo para esfriar incluído.", "about": "Bolo de cenoura com canela em forma de 20 cm, servido sem cobertura. Oito fatias, ingredientes pesados e tempo para esfriar incluído.", "faq": [{"q": "Leva cobertura de cream cheese?", "a": "Não. Acrescentar cobertura muda ingredientes, tempo e nutrição."}, {"q": "Posso usar uma forma menor?", "a": "A massa ficará mais alta e precisará de outro tempo. A referência é 20 cm; confira sempre o centro."}, {"q": "Por que não espremer a cenoura?", "a": "A fórmula considera sua umidade natural. Espremer muda o equilíbrio entre líquidos e farinha."}], "image_alt": "Bolo de cenoura com canela, sem cobertura", "image_variants": ["/recetas/receta-torta-de-zanahoria/portada-1x1.webp", "/recetas/receta-torta-de-zanahoria/portada-4x3.webp", "/recetas/receta-torta-de-zanahoria/portada-16x9.webp"]}, "nutrition": {"calories": 314.6, "protein_g": 4.8, "carbs_g": 42.7, "fat_g": 14.3, "saturated_fat_g": 1.4, "fiber_g": 1.8, "sugar_g": 21.6, "sodium_mg": 171.0, "serving_size": "Uma de 8 porções iguais", "estimated": true, "source": "USDA FoodData Central — SR Legacy (2018)", "method": "Soma dos gramas comestíveis iniciais × nutrientes USDA por 100 g, dividida por 8. Não se aplicam perdas de cocção não medidas. A fórmula inteira é dividida em oito fatias iguais. Não inclui cobertura, castanhas nem acompanhamentos.", "note": "Estimativa, não análise de laboratório nem teste de cozinha. Marcas, resíduos e rendimento podem variar. A fórmula inteira é dividida em oito fatias iguais. Não inclui cobertura, castanhas nem acompanhamentos.", "inputs": [{"fdc_id": 170